import json
import math
import random
import statistics
from pathlib import Path

root = Path("/tmp/opencode/task824/evaluation")


def comparison(before, after):
    ratios = [math.log(b / a) for a, b in zip(before, after, strict=True)]
    blocks = [ratios[i:i + 2] for i in range(0, len(ratios), 2)]
    rng = random.Random(824)
    samples = sorted(
        math.expm1(statistics.mean(
            value for block in rng.choices(blocks, k=len(blocks)) for value in block
        )) * 100
        for _ in range(10000)
    )
    return {
        "baseline": before, "candidate": after,
        "change_percent": math.expm1(statistics.mean(ratios)) * 100,
        "interval_percent": [samples[249], samples[9749]],
    }


summary = {"method": "Untrimmed geometric mean of paired ratios; 95% percentile bootstrap of adjacent two-pair blocks, 10000 resamples, seed 824. Intervals do not cover persistent drift."}
for path in sorted(root.glob("*-counters.json")) + sorted(root.glob("raw-*.json")):
    data = json.loads(path.read_text())
    summary[path.stem] = {
        metric: comparison(data["per_request"][data["control"]][metric],
                           data["per_request"][data["candidate"]][metric])
        for metric in ("instructions", "cycles")
    }
for path in sorted(root.glob("*-throughput.json")):
    data = json.loads(path.read_text())
    summary[path.stem] = comparison(data["rps"][data["control"]],
                                    data["rps"][data["candidate"]])
for label, candidate in (("aa", "base-control"), ("ab", "pgo")):
    arms = {
        arm: [json.loads((root / f"arrival-{label}-{pair}-{arm}.json").read_text())
              for pair in range(6)]
        for arm in ("baseline", candidate)
    }
    result = {
        metric: comparison(
            [r["metrics"]["http_req_duration"][metric] for r in arms["baseline"]],
            [r["metrics"]["http_req_duration"][metric] for r in arms[candidate]],
        )
        for metric in ("p(99)", "p(99.9)")
    }
    result["dropped_iterations"] = {
        arm: [r["metrics"].get("dropped_iterations", {}).get("count", 0) for r in rows]
        for arm, rows in arms.items()
    }
    result["completed_requests"] = {
        arm: [r["metrics"]["http_reqs"]["count"] for r in rows]
        for arm, rows in arms.items()
    }
    assert all(r["metrics"]["checks"]["fails"] == 0 for rows in arms.values() for r in rows)
    summary[f"arrival-{label}"] = result
startup = json.loads((root / "startup.json").read_text())
summary["startup"] = comparison(
    [r["seconds"] for r in startup if r["variant"] == "baseline"],
    [r["seconds"] for r in startup if r["variant"] == "pgo"],
)
summary["startup"]["mean_seconds"] = {
    arm: statistics.mean(r["seconds"] for r in startup if r["variant"] == arm)
    for arm in ("baseline", "pgo")
}
tail = root.parent / "tail-followup"
for label, candidate in (("aa", "base-control"), ("ab", "pgo")):
    arms = {
        arm: [json.loads((tail / f"{label}-{block}-{arm}.json").read_text())
              for block in range(12)]
        for arm in ("baseline", candidate)
    }
    result = {
        metric: comparison(
            [r["metrics"]["http_req_duration"][metric] for r in arms["baseline"]],
            [r["metrics"]["http_req_duration"][metric] for r in arms[candidate]],
        )
        for metric in ("p(99)", "p(99.9)")
    }
    result["dropped_iterations"] = {
        arm: [r["metrics"].get("dropped_iterations", {}).get("count", 0) for r in rows]
        for arm, rows in arms.items()
    }
    result["completed_requests"] = {
        arm: [r["metrics"]["http_reqs"]["count"] for r in rows]
        for arm, rows in arms.items()
    }
    assert all(r["metrics"]["checks"]["fails"] == 0 for rows in arms.values() for r in rows)
    summary[f"interleaved-arrival-{label}"] = result
(root / "summary.json").write_text(json.dumps(summary, indent=2) + "\n")
for name, result in summary.items():
    print(name, json.dumps(result))

