import http from 'k6/http';
import { check } from 'k6';

export const options = {
  scenarios: {
    requests: {
      executor: 'constant-arrival-rate',
      rate: Number(__ENV.RATE),
      timeUnit: '1s',
      duration: '8s',
      preAllocatedVUs: 100,
      maxVUs: 500,
      gracefulStop: '15s',
    },
  },
  summaryTrendStats: ['avg', 'p(50)', 'p(90)', 'p(95)', 'p(99)', 'p(99.9)', 'max'],
  thresholds: { http_req_failed: ['rate==0'], checks: ['rate==1'] },
};

export default function () {
  const result = http.get('http://127.0.0.1:8000/');
  check(result, {
    'validated response': r => r.status === 200
      && r.body === '{"id":17,"name":"public","tags":["held-out","json"],"active":true}',
  });
}
